beforeHooks.code:
const username =
                    process.env.TEST_USERNAME;
                const password =
                    process.env.TEST_PASSWORD;
                assert.ok(
                    username,
                    "未设置 TEST_USERNAME"
                );
                assert.ok(
                    password,
                    "未设置 TEST_PASSWORD"
                );
                driver =
                    await new Builder()
                        .forBrowser(
                            Browser.CHROME
                        )
                        .build();
                loginPage =
                    new RealLoginPage(
                        driver
                    );
                aiPage =
                    new AIAssistantPage(
                        driver
                    );
                // ======================================
                // 登录
                // ======================================
                await loginPage.open();
                await loginPage.login(
                    username,
                    password
                );
                // ======================================
                // 等登录完成
                // ======================================
                await driver.wait(
                    async () => {
                        const url =
                            await driver
                                .getCurrentUrl();
                        return !url.includes(
                            "/login"
                        );
                    },
                    20000,
                    "登录失败，仍停留在登录页"
                );
                // ======================================
                // 等 AI助手 导航出现
                // ======================================
                await driver.wait(
                    async () => {
                        const elements =
                            await driver.findElements(
                                By.xpath(
                                    '//*[normalize-space(.)="AI助手"]'
                                )
                            );
                        for (const element of elements) {
                            try {
                                if (
                                    await element.isDisplayed()
                                ) {
                                    return true;
                                }
                            } catch (error) {
                                // 继续
                            }
                        }
                        return false;
                    },
                    20000,
                    "登录后没有看到 AI助手 导航"
                );
                await driver.sleep(
                    500
                );

afterHooks.code:
try {
                    if (
                        driver &&
                        this.currentTest &&
                        this.currentTest.state
                            === "failed"
                    ) {
                        const image =
                            await driver
                                .takeScreenshot();
                        const testName =
                            this.currentTest
                                .title
                                .replace(
                                    /[\\/:*?"<>|]/g,
                                    "_"
                                );
                        const screenshotPath =
                            path.join(
                                screenshotsDir,
                                `${Date.now()}-${testName}.png`
                            );
                        fs.writeFileSync(
                            screenshotPath,
                            image,
                            "base64"
                        );
                        console.log(
                            "\nAI助手测试失败，截图已保存："
                        );
                        console.log(
                            screenshotPath
                        );
                    }
                } finally {
                    if (driver) {
                        try {
                            await driver.quit();
                        } catch (error) {
                            // 忽略
                        }
                        driver =
                            null;
                    }
                }

tests.code:
await aiPage.open();
                assert.equal(
                    await aiPage.isOpen(),
                    true,
                    "AI助手没有成功展开"
                );

await aiPage.open();
                assert.equal(
                    await aiPage
                        .isChatTabVisible(),
                    true,
                    "没有看到对话功能"
                );
                assert.equal(
                    await aiPage
                        .isRecommendTabVisible(),
                    true,
                    "没有看到推荐功能"
                );
                assert.equal(
                    await aiPage
                        .isWriteTabVisible(),
                    true,
                    "没有看到写作功能"
                );

await aiPage.open();
                assert.equal(
                    await aiPage
                        .isInputVisible(),
                    true,
                    "AI助手输入框没有显示"
                );

await aiPage.open();
                const message =
                    "帮我推荐学习 Python 的网站";
                await aiPage.typeMessage(
                    message
                );
                const value =
                    await aiPage
                        .getInputValue();
                assert.equal(
                    value,
                    message,
                    "AI助手输入框内容不正确"
                );

await aiPage.open();
                assert.equal(
                    await aiPage.isOpen(),
                    true
                );
                await aiPage.closeByX();
                assert.equal(
                    await aiPage.isOpen(),
                    false,
                    "AI助手关闭失败"
                );

await aiPage.open();
                await aiPage.closeByX();
                assert.equal(
                    await aiPage.isOpen(),
                    false
                );
                await aiPage.open();
                assert.equal(
                    await aiPage.isOpen(),
                    true,
                    "AI助手第二次打开失败"
                );
